"use client";

import React, { useState } from "react";

import Link from "next/link";

import { ModeToggle } from "@/components/ui/mode-toggle";
import { motion } from "framer-motion";

import { CardBody, CardContainer, CardItem } from "./3dCard";
import MobileNav from "./MobileNavBasic";

// import { debounce } from "../utils/debounce";

// https://ui.aceternity.com/components/navbar-menu

const transition = {
	type: "spring",
	mass: 0.5,
	damping: 11.5,
	stiffness: 100,
	restDelta: 0.001,
	restSpeed: 0.001,
};

export const MenuItem = ({
	setActive,
	active,
	item,
	children,
	to,
	uuid,
}: {
	setActive: (item: string) => void;
	active: string | null;
	item: string;
	children?: React.ReactNode;
	to?: string;
	uuid?: string;
}) => {
	return (
		<div
			onMouseEnter={() => setActive(item)}
			className="relative z-50 px-2 py-6"
			key={uuid || null}
		>
			<motion.p
				transition={{ duration: 0.3 }}
				className="cursor-default text-black hover:opacity-[0.9] dark:text-white"
			>
				{item}
			</motion.p>
			{active !== null && (
				<motion.div
					initial={{ opacity: 0, scale: 0.85, y: 10, borderRadius: "6px" }}
					animate={{ opacity: 1, scale: 1, y: 0 }}
					transition={transition}
					className=""
				>
					{active === item && (
						<div className="absolute left-1/2 transform -translate-x-1/2 pt-4">
							<motion.div
								transition={transition}
								layoutId="active" // layoutId ensures smooth animation
								className="bg-white dark:bg-gray-800 backdrop-blur-sm rounded-md overflow-hidden border border-black/[0.2] dark:border-white/[0.2] shadow-xl"
							>
								<motion.div
									layout // layout ensures smooth animation
									className="w-max h-full p-4"
								>
									{children}
								</motion.div>
							</motion.div>
						</div>
					)}
				</motion.div>
			)}
		</div>
	);
};

export const Menu = ({
	setActive,
	children,
}: {
	setActive: (item: string | null) => void;
	children: React.ReactNode;
}) => {
	return (
		<div className="relative w-full border border-transparent dark:bg-gray-800 dark:border-white/[0.2] bg-white shadow-input flex justify-center">
			<div
				onMouseLeave={() => setActive(null)} // resets the state
				className="flex justify-center items-center px-1 lg:w-full my-4"
			>
				{children}
			</div>
		</div>
	);
};

export const ThreeDProductItem = ({
	title,
	description,
	href,
	src,
	...rest
}: {
	title: string;
	description: string;
	href: string;
	src: string;
}) => {
	return (
		<CardContainer containerClassName="flex space-x-2 p-4" {...rest}>
			<CardBody className="h-24 w-24">
				<CardItem translateZ={400}>
					<img
						src={src}
						width={70}
						height={35}
						alt={title}
						className="flex-shrink-0 rounded-md shadow-2xl object-cover"
					/>
				</CardItem>
				<CardItem>
					<h4 className="text-xl font-bold mb-1 text-black dark:text-white">
						{title}
					</h4>
					<p className="text-neutral-700 text-sm max-w-[10rem] dark:text-neutral-300">
						{description}
					</p>
				</CardItem>
			</CardBody>
		</CardContainer>
	);
};

export const ProductItem = ({
	title,
	description,
	href,
	src,
	...rest
}: {
	title: string;
	description: string;
	href: string;
	src: string;
}) => {
	return (
		<div className="flex space-x-2" {...rest}>
			<img
				src={src}
				width={70}
				height={35}
				alt={title}
				className="flex-shrink-0 rounded-md shadow-2xl object-cover"
			/>
			<div>
				<h4 className="text-xl font-bold mb-1 text-black dark:text-white">
					{title}
				</h4>
				<p className="text-neutral-700 text-sm max-w-[10rem] dark:text-neutral-300">
					{description}
				</p>
			</div>
		</div>
	);
};

export const HoveredLink = ({ children, ...rest }: any) => {
	return (
		<Link
			{...rest}
			prefetch={false}
			className="text-neutral-700 dark:text-neutral-200 hover:text-black "
		>
			{children}
		</Link>
	);
};

const NavBar = ({ routes }: { routes: any[] }) => {
	const [selected, setSelected] = useState(null);
	const [hovered, setHovered] = useState(null);

	const checkDescendants = (route: any) => {
		return route.descendants.map((routeDescendant: any) => {
			if (
				!!routeDescendant.descendants &&
				!!routeDescendant.descendants.length
			) {
				return (
					<div key={routeDescendant.slug}>
						<p>
							{routeDescendant.title}
							<span className={""}>&gt;</span>
						</p>
						{routeDescendant.descendants.map(checkDescendants)}
					</div>
				);
			}

			// Only render routes directly below the header route
			return route.level + 1 === routeDescendant.level ? (
				<HoveredLink
					href={`/${routeDescendant.uri}`}
					key={routeDescendant.slug}
					onMouseEnter={() => setHovered(routeDescendant)}
				>
					{routeDescendant.title}
				</HoveredLink>
			) : null;
		});
	};

	return (
		<div className="dark:text-white relative z-50">
			<MobileNav />
			<header className="hidden md:block">
				<Menu setActive={setSelected}>
					{routes
						?.filter(
							(route) => route.level === 1 || route.typeHandle === "home"
						)
						?.map((route) => {
							return !!route.children.length ||
								route.typeHandle === "newsListing" ? (
								<MenuItem
									to={route.slug}
									item={route.title}
									setActive={setSelected}
									active={selected}
									uuid={route.slug}
								>
									<div className="flex">
										{hovered?.headerImage?.[0] ? (
											<img src={hovered?.headerImage[0].url} />
										) : (
											<div
												role="status"
												className="space-y-8 animate-pulse md:space-y-0 md:space-x-8 rtl:space-x-reverse md:flex md:items-center"
											>
												<div className="flex items-center justify-center w-full h-48 bg-gray-300 rounded sm:w-96 dark:bg-gray-700">
													<svg
														className="w-10 h-10 text-gray-200 dark:text-gray-600"
														aria-hidden="true"
														xmlns="http://www.w3.org/2000/svg"
														fill="currentColor"
														viewBox="0 0 20 18"
													>
														<path d="M18 0H2a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2V2a2 2 0 0 0-2-2Zm-5.5 4a1.5 1.5 0 1 1 0 3 1.5 1.5 0 0 1 0-3Zm4.376 10.481A1 1 0 0 1 16 15H4a1 1 0 0 1-.895-1.447l3.5-7A1 1 0 0 1 7.468 6a.965.965 0 0 1 .9.5l2.775 4.757 1.546-1.887a1 1 0 0 1 1.618.1l2.541 4a1 1 0 0 1 .028 1.011Z" />
													</svg>
												</div>
											</div>
										)}
										<div className="text-sm grid grid-cols-3 md:grid-cols-4 gap-5 p-4">
											{route.typeHandle === "newsListing"
												? routes
														.filter(
															(route) =>
																route.typeHandle === "news"
														)
														.map((item) => (
															<HoveredLink
																href={`/${item.uri}`}
																key={item.slug}
																onMouseEnter={() =>
																	setHovered(item)
																}
															>
																{item.title}
															</HoveredLink>
														))
												: route.children.map((item) => (
														<HoveredLink
															href={`/${item.uri}`}
															key={item.slug}
															onMouseEnter={() =>
																setHovered(item)
															}
														>
															{item.title}
														</HoveredLink>
													))}{" "}
										</div>
									</div>
								</MenuItem>
							) : (
								<Link
									prefetch={false}
									href={
										route.typeHandle === "home"
											? "/"
											: `/${route.uri}`
									}
									key={route.slug}
									onMouseEnter={() => {
										setHovered(null);
										setSelected(null);
									}}
									className="mx-2"
								>
									{route.title}
								</Link>
							);
						})}
					<Link
						prefetch={false}
						href={"https://www.admin.example.drivedev.net/access"}
						key={"admin"}
						onMouseEnter={() => {
							setHovered(null);
							setSelected(null);
						}}
						className="mx-2"
					>
						Admin
					</Link>
					{/* <Notice /> */}
					<div
						onMouseEnter={() => {
							setHovered(null);
							setSelected(null);
						}}
					>
						<ModeToggle />
					</div>
				</Menu>
			</header>
		</div>
	);
};

export default NavBar;

"use client";

import * as React from "react";

import { Button } from "@/components/ui/button";
import { Moon, Sun } from "lucide-react";
import { useTheme } from "next-themes";

export function ModeToggle({ className }) {
	const { setTheme, theme } = useTheme();

	return (
		<Button
			size="icon"
			onClick={() => setTheme(theme === "light" ? "dark" : "light")}
			className={className}
		>
			<Sun className="h-[1.2rem] w-[1.2rem] rotate-0 scale-100 transition-all dark:-rotate-90 dark:scale-0" />
			<Moon className="absolute h-[1.2rem] w-[1.2rem] rotate-90 scale-0 transition-all dark:rotate-0 dark:scale-100" />
			<span className="sr-only">Toggle theme</span>
		</Button>
	);
}

import * as React from "react";

import { cn } from "@/lib/utils";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";

const buttonVariants = cva(
	"inline-flex items-center justify-center whitespace-nowrap rounded-md text-sm text-white hover:text-gray-400 font-medium ring-offset-background transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50",
	{
		variants: {
			variant: {
				simple:
					"bg-secondary relative z-10 bg-transparent hover:border-secondary hover:bg-secondary/50  border border-transparent dark:text-white text-sm md:text-sm transition font-medium duration-200  rounded-md px-4 py-2  flex items-center justify-center",
				default: "bg-primary text-primary-foreground hover:bg-primary/90",
				destructive:
					"bg-destructive text-destructive-foreground hover:bg-destructive/90",
				outline:
					"border border-input bg-background hover:bg-accent hover:text-accent-foreground",
				secondary:
					"bg-secondary text-secondary-foreground hover:bg-secondary/80",
				ghost: "hover:bg-accent hover:text-black hover:stroke-black dark:text-white text-black",
				link: "text-primary underline-offset-4 hover:underline",
			},
			size: {
				default: "h-10 px-4 py-2",
				sm: "h-9 rounded-md px-3",
				lg: "h-11 rounded-md px-8",
				icon: "h-10 w-10",
			},
		},
		defaultVariants: {
			variant: "default",
			size: "default",
		},
	}
);

export interface ButtonProps
	extends React.ButtonHTMLAttributes<HTMLButtonElement>,
		VariantProps<typeof buttonVariants> {
	asChild?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
	({ className, variant, size, asChild = false, ...props }, ref) => {
		const Comp = asChild ? Slot : "button";
		return (
			<Comp
				className={cn(buttonVariants({ variant, size, className }))}
				ref={ref}
				{...props}
			/>
		);
	}
);
Button.displayName = "Button";

export { Button, buttonVariants };

import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

"use client";

import React, {
	createContext,
	useContext,
	useEffect,
	useRef,
	useState,
} from "react";

import { cn } from "@/lib/utils";

// https://ui.aceternity.com/components/3d-card-effect

const MouseEnterContext = createContext<
	[boolean, React.Dispatch<React.SetStateAction<boolean>>] | undefined
>(undefined);

export const CardContainer = ({
	children,
	className,
	containerClassName,
	id,
	title,
}: {
	children?: React.ReactNode;
	className?: string;
	containerClassName?: string;
	id?: string;
	title?: string;
}) => {
	const containerRef = useRef<HTMLDivElement>(null);
	const [isMouseEntered, setIsMouseEntered] = useState(false);

	const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
		if (!containerRef.current) return;
		const { left, top, width, height } =
			containerRef.current.getBoundingClientRect();
		const x = (e.clientX - left - width / 2) / 25;
		const y = (e.clientY - top - height / 2) / 25;
		containerRef.current.style.transform = `rotateY(${x}deg) rotateX(${y}deg)`;
	};

	const handleMouseEnter = () => {
		setIsMouseEntered(true);
		if (!containerRef.current) return;
	};

	const handleMouseLeave = () => {
		if (!containerRef.current) return;
		setIsMouseEntered(false);
		containerRef.current.style.transform = `rotateY(0deg) rotateX(0deg)`;
	};
	return (
		<MouseEnterContext.Provider value={[isMouseEntered, setIsMouseEntered]}>
			<div
				className={cn(
					"pt-20 flex items-center justify-center",
					containerClassName
				)}
				style={{
					perspective: "1000px",
				}}
				id={id}
				title={title}
			>
				<div
					ref={containerRef}
					onMouseEnter={handleMouseEnter}
					onMouseMove={handleMouseMove}
					onMouseLeave={handleMouseLeave}
					className={cn(
						"flex items-center justify-center relative transition-all duration-200 ease-linear",
						className
					)}
					style={{
						transformStyle: "preserve-3d",
					}}
				>
					{children}
				</div>
			</div>
		</MouseEnterContext.Provider>
	);
};

export const CardBody = ({
	children,
	className,
}: {
	children: React.ReactNode;
	className?: string;
}) => {
	return (
		<div
			className={cn(
				"[transform-style:preserve-3d]  [&>*]:[transform-style:preserve-3d]",
				className
			)}
		>
			{children}
		</div>
	);
};

export const CardItem = ({
	as: Tag = "div",
	children,
	className,
	translateX = 0,
	translateY = 0,
	translateZ = 0,
	rotateX = 0,
	rotateY = 0,
	rotateZ = 0,
	...rest
}: {
	as?: React.ElementType;
	children: React.ReactNode;
	className?: string;
	translateX?: number | string;
	translateY?: number | string;
	translateZ?: number | string;
	rotateX?: number | string;
	rotateY?: number | string;
	rotateZ?: number | string;
	[key: string]: any;
}) => {
	const ref = useRef<HTMLDivElement>(null);
	const [isMouseEntered] = useMouseEnter();

	useEffect(() => {
		handleAnimations();
	}, [isMouseEntered]);

	const handleAnimations = () => {
		if (!ref.current) return;
		if (isMouseEntered) {
			ref.current.style.transform = `translateX(${translateX}px) translateY(${translateY}px) translateZ(${translateZ}px) rotateX(${rotateX}deg) rotateY(${rotateY}deg) rotateZ(${rotateZ}deg)`;
		} else {
			ref.current.style.transform = `translateX(0px) translateY(0px) translateZ(0px) rotateX(0deg) rotateY(0deg) rotateZ(0deg)`;
		}
	};

	return (
		<Tag
			ref={ref}
			className={cn("transition duration-200 ease-linear", className)}
			{...rest}
		>
			{children}
		</Tag>
	);
};

// Create a hook to use the context
export const useMouseEnter = () => {
	const context = useContext(MouseEnterContext);
	if (context === undefined) {
		throw new Error("useMouseEnter must be used within a MouseEnterProvider");
	}
	return context;
};
